import { computed, Directive, effect, ElementRef, inject, input, NgModule, Renderer2, SecurityContext, signal } from '@angular/core';
import { DomSanitizer } from '@angular/platform-browser';
import { cn, equals } from '@primeuix/utils';

const SANITIZED_SINKS: { [key: string]: SecurityContext } = {
    innerhtml: SecurityContext.HTML,
    srcdoc: SecurityContext.HTML,
    href: SecurityContext.URL,
    src: SecurityContext.URL,
    action: SecurityContext.URL,
    formaction: SecurityContext.URL
};

const REJECTED_SINKS = new Set(['outerhtml']);

/**
 * Bind directive provides dynamic attribute, property, and event listener binding functionality.
 * @group Components
 */
@Directive({
    selector: '[pBind]',
    standalone: true,
    host: {
        '[style]': 'styles()',
        '[class]': 'classes()'
    }
})
export class Bind {
    /**
     * Dynamic attributes, properties, and event listeners to be applied to the host element.
     * @group Props
     */
    pBind = input<{ [key: string]: any } | undefined>(undefined);

    private _attrs = signal<{ [key: string]: any } | undefined>(undefined);
    private attrs = computed(() => this._attrs() || this.pBind());

    styles = computed(() => this.attrs()?.style);
    classes = computed(() => cn(this.attrs()?.class));

    private listeners: { eventName: string; unlisten: () => void }[] = [];

    private el = inject(ElementRef);

    private renderer = inject(Renderer2);

    private sanitizer = inject(DomSanitizer);

    constructor() {
        effect(() => {
            const attrs = this.attrs() || {};
            const rest = Object.fromEntries(Object.entries(attrs).filter(([key]) => key !== 'style' && key !== 'class'));

            for (const [key, value] of Object.entries(rest)) {
                const normalizedKey = key.toLowerCase();

                if (normalizedKey.startsWith('on')) {
                    // Only function-valued listeners are supported; string values would become live inline handlers (XSS).
                    if (typeof value === 'function') {
                        const eventName = normalizedKey.slice(2);

                        // add listener if not already added
                        if (!this.listeners.some((l) => l.eventName === eventName)) {
                            const unlisten = this.renderer.listen(this.el.nativeElement, eventName, value);

                            this.listeners.push({ eventName, unlisten });
                        }
                    }
                } else if (value === null || value === undefined) {
                    // remove attr
                    this.renderer.removeAttribute(this.el.nativeElement, key);
                } else if (REJECTED_SINKS.has(normalizedKey)) {
                    continue;
                } else if (SANITIZED_SINKS[normalizedKey] !== undefined) {
                    const safe = this.sanitizer.sanitize(SANITIZED_SINKS[normalizedKey], value.toString()) ?? '';

                    this.renderer.setAttribute(this.el.nativeElement, key, safe);

                    if (key in this.el.nativeElement) {
                        (this.el.nativeElement as any)[key] = safe;
                    }
                } else {
                    // attr & prop fallback
                    this.renderer.setAttribute(this.el.nativeElement, key, value.toString());

                    if (key in this.el.nativeElement) {
                        (this.el.nativeElement as any)[key] = value;
                    }
                }
            }
        });
    }

    ngOnDestroy() {
        this.clearListeners();
    }

    public setAttrs(attrs: { [key: string]: any } | undefined) {
        if (!equals(this._attrs(), attrs)) {
            this._attrs.set(attrs);
        }
    }

    private clearListeners() {
        this.listeners.forEach(({ unlisten }) => unlisten());
        this.listeners = [];
    }
}

@NgModule({
    imports: [Bind],
    exports: [Bind]
})
export class BindModule {}
